from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'debugging'
CATALOG = [{'id': 'dbg-db-pool-leak', 'concept': 'db-connection-pool-leak', 'domain': 'software-engineering', 'subdomain': 'resource-management', 'difficulty': 'intermediate', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': "An API gradually slows over several hours. Database CPU remains low, but request traces show long waits before SQL begins and the application's connection pool reaches its maximum size. What would you measure to confirm a connection leak?", 'answer': 'Measure pool `in-use`, `idle`, waiters, checkout duration, and connection-return counts over time. Correlate those metrics with request paths and errors.\n\nA leak is supported when checked-out connections monotonically accumulate or remain held long after the owning request has finished, while the database itself has spare capacity. Capture stack/context information at checkout when practical and identify code paths that fail to return a connection on exceptions, cancellations, or early returns.\n\nIncreasing the pool may delay the symptom but does not fix leaked ownership.', 'verification_details': 'Must distinguish pool exhaustion from database saturation, inspect checkout/return lifetime metrics, correlate leaked ownership with request paths, and reject pool-size increase as the root fix.', 'tags': ['database', 'connection-pool', 'leak', 'latency']}, {'id': 'dbg-emfile-accept-path', 'concept': 'emfile-server-accept-recovery', 'domain': 'systems-programming', 'subdomain': 'file-descriptors', 'difficulty': 'advanced', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'A Unix server intermittently stops accepting new connections and logs `EMFILE`. Logging itself also becomes unreliable at the same time. Give a debugging and recovery plan.', 'answer': 'Inspect per-process and system-wide descriptor limits, current open descriptor count, and descriptor growth by type. Identify leaked sockets/files rather than assuming the limit is simply too small.\n\nFor the accept path, keep a reserved descriptor available. On `EMFILE`, close the reserve, accept and close one pending connection so the listen queue can make progress, reopen the reserve, and enter controlled backoff/load shedding while the leak is investigated.\n\nUse logging that does not depend on opening new files at the failure point, and export descriptor metrics before exhaustion occurs. Raising `RLIMIT_NOFILE` can provide headroom but is not a substitute for fixing unbounded descriptor lifetime.', 'verification_details': 'Must measure descriptor usage/leaks, explain why EMFILE can break accept and logging, provide a bounded recovery pattern such as a reserved descriptor, and avoid treating a higher limit as the only fix.', 'tags': ['emfile', 'file-descriptor', 'accept', 'resource-leak']}, {'id': 'dbg-direct-reclaim', 'concept': 'direct-reclaim-latency-stalls', 'domain': 'operating-systems', 'subdomain': 'memory-management', 'difficulty': 'advanced', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'A latency-sensitive Linux process experiences long stalls during memory pressure even though it is not being OOM-killed. CPU profiles show time in kernel reclaim paths. How would you determine whether direct reclaim is on the request path?', 'answer': 'Correlate latency spikes with memory-pressure signals: reclaim counters, PSI memory stall time, major/minor fault activity, allocation stalls, and traces showing the request thread entering reclaim/compaction.\n\nDirect reclaim is supported when the allocating application thread itself spends significant time reclaiming pages because free memory/watermarks cannot satisfy the allocation promptly.\n\nInspect working-set size, page-cache pressure, cgroup limits, swap behavior, and high-order allocation/compaction if relevant. The remedy is to reduce/reshape memory pressure or provision headroom; simply adding CPU does not remove time spent synchronously reclaiming memory.', 'verification_details': 'Must correlate request latency with reclaim/PSI evidence, identify the application thread entering direct reclaim, inspect memory/cgroup/swap pressure, and avoid misdiagnosing it as a CPU-capacity problem.', 'tags': ['linux', 'direct-reclaim', 'psi', 'latency']}, {'id': 'dbg-lock-convoy', 'concept': 'mutex-lock-convoy', 'domain': 'operating-systems', 'subdomain': 'synchronization', 'difficulty': 'expert', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'Throughput collapses as thread count rises. A profiler shows many threads sleeping on one mutex, but the critical section is individually short. Explain how to test whether lock convoying and handoff overhead are dominating.', 'answer': 'Measure mutex wait time, hold time, wakeups/context switches, runnable-thread count, and throughput as concurrency increases. A convoy is indicated when ownership repeatedly passes through a long queue of blocked threads and scheduling/wakeup overhead becomes large relative to the useful critical section.\n\nCompare with a run using fewer worker threads and, where possible, shard the protected state or batch operations to reduce acquisition frequency. A design with per-core/per-shard locks should reduce wait queues if contention is the cause.\n\nDo not infer the problem from mutex presence alone: verify that aggregate waiting and handoff cost scales with the throughput collapse.', 'verification_details': 'Must measure wait/hold/handoff behavior versus concurrency, identify queued ownership transfer as the convoy mechanism, and validate by reducing contention or worker count.', 'tags': ['mutex', 'convoy', 'contention', 'scheduler']}, {'id': 'dbg-arm-publication-order', 'concept': 'weak-memory-publication-bug', 'domain': 'computer-architecture', 'subdomain': 'memory-ordering', 'difficulty': 'expert', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'A lock-free object publication pattern works on x86 in testing but occasionally exposes partially initialized fields on ARM. The publisher writes fields and then stores a non-null pointer with relaxed ordering; the reader loads the pointer relaxed and dereferences it. Diagnose the bug.', 'answer': 'The pointer becoming visible does not, with relaxed operations alone, establish the required happens-before relationship for the preceding field initialization.\n\nPublish the pointer with release semantics after initialization and load it with acquire semantics before dereferencing. The acquire load that observes the release-published pointer makes the prior initialization visible according to the language memory model.\n\nThe fact that x86 testing appears reliable is not proof of correctness; stronger hardware ordering can mask a language-level synchronization bug that appears on weaker architectures.', 'verification_details': 'Must identify missing publication ordering, require release store plus acquire load (or equivalent synchronization), and explain why x86 success can mask the bug.', 'tags': ['arm', 'memory-model', 'acquire-release', 'lock-free']}, {'id': 'dbg-systemd-environment', 'concept': 'systemd-shell-environment-mismatch', 'domain': 'linux-infrastructure', 'subdomain': 'service-management', 'difficulty': 'intermediate', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'A program works when started from an interactive shell but fails when started by systemd because it cannot find a helper executable and uses the wrong configuration directory. What should be compared?', 'answer': "Compare the service unit's actual environment with the interactive shell: `PATH`, working directory, user/group, environment files, home directory assumptions, and any shell startup scripts that are not executed by systemd.\n\nUse absolute paths for important executables/configuration where appropriate and declare `WorkingDirectory=`, `Environment=`, `EnvironmentFile=`, credentials, and permissions explicitly in the unit rather than depending on an interactive login environment.\n\nInspect the effective unit with systemd tooling and the service journal. The fix is to make runtime dependencies explicit, not to source a user's shell profile blindly.", 'verification_details': 'Must compare PATH/working directory/user/environment differences, make unit dependencies explicit, and avoid relying on interactive shell startup files.', 'tags': ['systemd', 'environment', 'path', 'service']}, {'id': 'dbg-brownout-reset', 'concept': 'brownout-vs-watchdog-reset-diagnosis', 'domain': 'embedded-systems', 'subdomain': 'power-integrity', 'difficulty': 'advanced', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'An MCU resets only when a motor starts. The firmware team suspects the watchdog because the symptom is a reboot. How would you determine whether supply brownout is the real cause?', 'answer': 'Read and preserve the MCU reset-cause flags immediately after boot so brownout/power-on/watchdog causes are not overwritten by later initialization.\n\nMeasure the supply rail at the MCU with an oscilloscope during motor startup, including ground reference and transient duration, and compare the dip with the brownout detector threshold and decoupling requirements.\n\nAlso log whether the watchdog was actually armed and whether its reset flag is set. A reset coincident with a rail dip below threshold and a brownout cause flag strongly supports power integrity as the cause. Fix the power path, decoupling, sequencing, or load transient rather than weakening watchdog protection.', 'verification_details': 'Must inspect reset-cause flags and supply transients, compare them with brownout thresholds, independently verify watchdog state, and keep the watchdog enabled.', 'tags': ['embedded', 'brownout', 'watchdog', 'power']}, {'id': 'dbg-ephemeral-port-exhaustion', 'concept': 'client-ephemeral-port-exhaustion', 'domain': 'networking', 'subdomain': 'tcp', 'difficulty': 'advanced', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'A client host making many short-lived outbound TCP connections begins failing to connect even though the remote service is healthy. Local CPU and bandwidth are low. How would you test for ephemeral-port exhaustion?', 'answer': 'Inspect the local ephemeral port range, active connection count, socket states such as `TIME_WAIT`, and connection errors such as address/port allocation failures. Include the destination tuple because available source ports are consumed in the context of connection identity and NAT may impose an additional external limit.\n\nIf failures rise as the usable local/NAT port space is occupied by active or TIME_WAIT connections, port exhaustion is plausible.\n\nPrefer connection reuse/pooling or multiplexed protocols where suitable. Expanding the local range can add headroom, but aggressive unsafe TIME_WAIT changes are not a substitute for fixing excessive connection churn.', 'verification_details': 'Must inspect ephemeral range, socket states/errors and possible NAT limits, connect failures to occupied tuple space, and prefer reducing connection churn over unsafe TIME_WAIT shortcuts.', 'tags': ['tcp', 'ephemeral-port', 'time-wait', 'connection-churn']}, {'id': 'dbg-cuda-default-stream', 'concept': 'cuda-default-stream-serialization', 'domain': 'compute-model-infrastructure', 'subdomain': 'gpu-scheduling', 'difficulty': 'expert', 'task_type': 'debugging', 'verification_method': 'rubric', 'question': 'A CUDA pipeline was intended to overlap host-to-device copies with kernels in separate streams, but the profiler shows large serialized gaps. Some helper code launches work on the default stream. What should be checked?', 'answer': 'Inspect the timeline by stream and identify operations submitted to the legacy/default stream or APIs that imply synchronization. Depending on the runtime/default-stream mode, default-stream work can introduce ordering with other streams and destroy intended overlap.\n\nVerify that copies use pinned host memory when asynchronous transfer is required, that stream dependencies are expressed with events rather than broad device synchronizations, and that helper libraries are given the intended stream.\n\nA before/after profiler trace should show copy and compute overlap increasing after removing unintended synchronization. Merely creating multiple streams does not guarantee concurrency.', 'verification_details': 'Must use a profiler timeline, inspect default-stream and implicit synchronization behavior, verify prerequisites such as pinned memory, and validate improved overlap after stream/dependency fixes.', 'tags': ['cuda', 'streams', 'overlap', 'profiling']}, {'id': 'dbg-mtls-san', 'concept': 'mtls-san-identity-mismatch', 'domain': 'secure-engineering', 'subdomain': 'tls', 'difficulty': 'advanced', 'task_type': 'debugging', 'verification_method': 'reference-answer', 'question': 'A service-to-service mTLS connection fails certificate identity verification after a deployment. The certificate chain is trusted and dates are valid. The client now connects using a new DNS name. What should be checked?', 'answer': "Inspect the peer certificate's Subject Alternative Name entries and the exact server identity the client is verifying.\n\nTrusting the issuing CA proves the certificate chains to a trusted authority; it does not mean the certificate is valid for every hostname. If the new DNS name is absent from the relevant SAN entries, hostname verification should fail even though the chain and validity dates are correct.\n\nIssue/use a certificate containing the intended service identities or connect through an identity already covered by policy. Do not disable hostname verification as a workaround.", 'verification_details': 'Must distinguish chain trust from endpoint identity, compare the requested DNS identity with SAN entries, and reject disabling hostname verification.', 'tags': ['mtls', 'san', 'hostname-verification', 'certificate']}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]

BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        x["task_type"],
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
